"""Reads BOM CSV files exported from KiCad or generated by KiBot.

KiCad's "Export BOM" and KiBot's CSV output both produce one row per group of
identical parts with columns such as Reference(s), Value, Footprint, Quantity,
and optional fields such as MPN, Manufacturer and DNP. Column names vary, so
we match them loosely.
"""
import csv
import io
import re

COLUMN_ALIASES = {
    "references": ["references", "reference", "ref", "refs", "designator", "designators", "ref des", "refdes"],
    "value": ["value", "val", "comment"],
    "footprint": ["footprint", "package", "pcb footprint"],
    "quantity": ["quantity", "qty", "quantity per pcb", "qty per board", "count"],
    "mpn": ["mpn", "manf", "mfr pn", "mfr part number", "manufacturer part number", "manufacturer_part_number", "mfr part", "mfr. no", "part number", "mfn"],
    "manufacturer": ["manufacturer", "mfr", "mfg", "manufacturer name"],
    "datasheet": ["datasheet"],
    "description": ["description", "desc"],
    "dnp": ["dnp", "do not populate", "dnf", "exclude from bom"],
    "ipn": ["ipn", "internal part number", "workbench pn", "part id"],
}


MAX_QTY = 100_000


def _norm(h):
    return re.sub(r"[\s_]+", " ", (h or "").strip().lower().replace("#", ""))


def map_columns(headers):
    mapping = {}
    normalized = {_norm(h): h for h in headers}
    for field, aliases in COLUMN_ALIASES.items():
        for alias in aliases:
            if alias in normalized:
                mapping[field] = normalized[alias]
                break
    return mapping


def _truthy(v):
    return str(v).strip().lower() in {"1", "yes", "y", "true", "x", "dnp", "dnf"}


def _category_for(refs, value):
    first = (refs.split(",")[0] if refs else "").strip().upper()
    prefix = re.match(r"[A-Z]+", first)
    prefix = prefix.group(0) if prefix else ""
    return {
        "R": "resistor", "RN": "resistor", "C": "capacitor", "L": "inductor", "FB": "inductor",
        "D": "diode", "LED": "diode", "Q": "transistor", "U": "ic", "IC": "ic",
        "J": "connector", "P": "connector", "CN": "connector", "SW": "mechanical", "H": "mechanical",
        "MH": "mechanical", "Y": "other", "X": "other", "F": "other", "TP": "other",
    }.get(prefix, "other")


def parse(file_bytes):
    """Returns (rows, warnings). Each row is a dict with normalised keys."""
    warnings = []
    try:
        text = file_bytes.decode("utf-8-sig")
    except UnicodeDecodeError:
        # Excel on Windows saves CSV as Windows-1252 ("µ", "Ω", "±" would otherwise be garbled).
        text = file_bytes.decode("cp1252", errors="replace")
        warnings.append("The file isn't UTF-8, so it was read as Windows-1252 (Excel's default). "
                        "Check that symbols such as µ and Ω look right below.")
    sample = text[:4096]
    try:
        dialect = csv.Sniffer().sniff(sample, delimiters=",;\t")
    except csv.Error:
        dialect = csv.excel
    reader = csv.reader(io.StringIO(text), dialect)
    all_rows = [r for r in reader]
    # KiBot sometimes writes a title block before the header row; find the header.
    header_idx = 0
    for i, r in enumerate(all_rows[:15]):
        m = map_columns(r)
        if "references" in m or ("value" in m and "quantity" in m):
            header_idx = i
            break
    if not all_rows:
        return [], ["The file is empty."]
    headers = all_rows[header_idx]
    cols = map_columns(headers)
    if "references" not in cols and "quantity" not in cols:
        return [], ["Couldn't find a Reference or Quantity column. Export the BOM as CSV from KiCad or KiBot."]
    idx = {k: headers.index(v) for k, v in cols.items()}

    def get(r, k):
        i = idx.get(k)
        return r[i].strip() if i is not None and i < len(r) else ""

    rows = []
    for r in all_rows[header_idx + 1:]:
        if not any(c.strip() for c in r):
            continue
        refs = get(r, "references")
        refs = ", ".join(x for x in re.split(r"[\s,;]+", refs) if x)
        qty_raw = get(r, "quantity")
        value, footprint = get(r, "value"), get(r, "footprint")
        label = refs or value or footprint or "?"
        try:
            qty = int(float(qty_raw.replace(",", "."))) if qty_raw else len([x for x in refs.split(",") if x.strip()])
        except (ValueError, OverflowError):
            warnings.append(f"Row {label}: quantity “{qty_raw}” isn't a number, counted references instead.")
            qty = len([x for x in refs.split(",") if x.strip()]) or 1
        if qty <= 0:
            if not qty_raw and not refs:
                warnings.append(f"Row {label} has no references and no quantity, so it was skipped.")
            else:
                warnings.append(f"Row {label} has quantity {qty_raw or 0}, so it was skipped.")
            continue
        if qty > MAX_QTY:
            warnings.append(f"Row {label}: quantity {qty} is more than {MAX_QTY:,} per board, so it was skipped.")
            continue
        rows.append({
            "references": refs,
            "value": value,
            "footprint": footprint,
            "quantity": qty,
            "mpn": get(r, "mpn"),
            "manufacturer": get(r, "manufacturer"),
            "datasheet": get(r, "datasheet") if get(r, "datasheet").startswith("http") else "",
            "description": get(r, "description") or " ".join(x for x in [value, footprint.split(":")[-1]] if x),
            "dnp": _truthy(get(r, "dnp")),
            "ipn": get(r, "ipn"),
            "category": _category_for(refs, value),
        })
    if not rows:
        warnings.append("No part rows were found in the file.")
    return rows, warnings


def match_part(row):
    """Find an existing part for a BOM row: IPN, then MPN, then value+footprint."""
    from .models import Part
    if row.get("ipn"):
        p = Part.objects.filter(ipn__iexact=row["ipn"]).first()
        if p:
            return p, "part number"
    if row.get("mpn"):
        p = Part.objects.filter(mpn__iexact=row["mpn"]).first()
        if p:
            return p, "manufacturer part number"
    if row.get("value") and row.get("footprint"):
        p = Part.objects.filter(value__iexact=row["value"], footprint__iexact=row["footprint"]).first()
        if p:
            return p, "value + footprint"
    return None, ""
